158	      DiagnosticEventData::GetAsStructuredData(event.get());
159	
160	  if (!dictionary_sp)
161	    return {};
162	
163	  SBStructuredData data;
164	  data.m_impl_up->SetObjectSP(std::move(dictionary_sp));
165	  return data;
166	}
