182	lldb::SBError SBDebugger::InitializeWithErrorHandling() {
183	  LLDB_INSTRUMENT();
184	
185	  SBError error;
186	  if (auto e = g_debugger_lifetime->Initialize(
187	          std::make_unique<SystemInitializerFull>())) {
