1099	uint32_t SBDebugger::GetNumAvailablePlatforms() {
1100	  LLDB_INSTRUMENT_VA(this);
1101	
1102	  uint32_t idx = 0;
1103	  while (true) {
1104	    if (PluginManager::GetPlatformPluginNameAtIndex(idx).empty()) {
1105	      break;
1106	    }
1107	    ++idx;
1108	  }
1109	  // +1 for the host platform, which should always appear first in the list.
1110	  return idx + 1;
